import json,pathlib,hashlib,shutil,numpy as np
from shapely.geometry import shape,mapping,Point
from shapely.ops import transform,unary_union,nearest_points
from pyproj import Transformer
root=pathlib.Path('data/neighborhoods/sources/municipal-east');tmp=pathlib.Path('.local/neighborhoods/east-geometry')
j=json.loads((tmp/'eger-vector-paths.json').read_text());A=np.array(j['affineToEov']['matrix']);b=np.array(j['affineToEov']['offset']);rev=Transformer.from_crs(23700,4326,always_xy=True)
sourceurl='https://eger.hu/public/uploads/m2-melleklet-2016-0826_57d7ea2877316.pdf'
sourcepdf=pathlib.Path('.local/neighborhoods/nationwide-docs/originals/eger-map.pdf');docsha=hashlib.sha256(sourcepdf.read_bytes()).hexdigest()
# Names and plan identifiers were read directly from searchable labels and verified in the rendered source.
labels={164815:('Északkeleti külterület és Bikalegelő','V1.1.'),164816:('OMYA','3.29.'),164817:('Almár','3.28.'),164818:('Hajdúhegy','2.24.'),164819:('Szent Miklós','2.26.'),164820:('Belváros','2.25.'),164828:('Lajosváros – nyugat','2.23.'),164829:('Galagonyás-dűlő','3.27.'),164830:('Felnémet','M1.8.'),164831:('Nagylapos','M1.16.'),164832:('Volt kemping','M1.22.'),164833:('Rác hóstya','M1.17.'),164834:('Hajdúhegy észak','M1.10.'),164835:('Felsőváros','M1.9.'),164836:('Károlyváros','M1.12.'),164837:('Szépasszonyvölgy','M1.19.'),164838:('Hatvani hóstya','M1.11.'),164839:('K2 jelű út és környéke','M1.13.'),164842:('Déli iparterület','M1.6.'),164843:('Lajosváros kelet','M1.14.'),164844:('Délkeleti külterület','M1.7.'),164845:('Csákó','M1.5.'),164846:('Tihamér','M1.20.'),164847:('Maklári hóstya','M1.15.'),164848:('Almagyar – Merengő','M1.1.'),164849:('Sánc','M1.18.'),164850:('Belváros kelet','M1.3.'),164851:('Belváros Dobó tér','M1.2.'),164852:('Cifra hóstya – Tetemvár','M1.4.'),164853:('Vécseyvölgy','M1.21.'),165658:('Északnyugati külterület','M1.23.'),165659:('Északnyugati külterület – általános tervterület','TSZT2004')}
pdfgs={r['pdfDrawingIndex']:shape(r['pdfGeometry']) for r in j['paths']}
# Three nested planning polygons are genuine holes in the general TSZT area.
pdfgs[165659]=pdfgs[165659].difference(unary_union([pdfgs[i] for i in [164816,164817,165658]]))
def togeo(x,y,z=None):
 xx=A[0,0]*np.asarray(x)+A[0,1]*np.asarray(y)+b[0];yy=A[1,0]*np.asarray(x)+A[1,1]*np.asarray(y)+b[1]
 return rev.transform(xx,yy)
features=[]
for idx,(name,planid) in labels.items():
 geo=transform(togeo,pdfgs[idx]);assert geo.is_valid and not geo.is_empty
 features.append({'type':'Feature','id':f'municipal:eger:plan:{idx}','properties':{'name':name,'municipality':'Eger','boundaryKind':'planning_unit','method':'original_pdf_vector_path_affine_georeferencing','evidenceUrls':[sourceurl,'https://www.openstreetmap.org/relation/1418156'],'sourceDocuments':[{'url':sourceurl,'sha256':docsha,'page':1,'referenceDate':'2016-08'}],'sourcePlanId':planid,'sourcePdfDrawingIndex':idx,'controlPoints':{'method':'Iterative closest-boundary affine fit to Eger municipal OSM boundary in EPSG23700','targetOsmRelationId':1418156,'sourceBoundaryDrawingIndices':list(range(164771,164780)),'affineToEov':j['affineToEov'],'boundaryMatchResidualMeters':j['boundaryMatchResidualMeters']},'quality':{'status':'historical_planning_geometry_review_required','referenceYear':2016,'geometryValid':True,'boundaryMatchP95Meters':j['boundaryMatchResidualMeters']['p95'],'independentInteriorControlVerified':False,'semanticExtent':'Regulatory planning unit from official HÉSZ annex; not asserted identical to common-name neighborhood'},'reviewNotes':['Preserves original vector boundary segments; PDF float coordinates normalized at0.001point (<0.01m).','Georeferencing uses a full municipal-boundary match, not independently surveyed interior controls; address-level accuracy is unverified.','The general TSZT polygon retains holes occupied by separately mapped OMYA, Almár, and M1.23 planning areas.','Source-map reuse rights are not established; geometry is an auditable research artifact.'],'usableForAddressAssignment':False,'licenseStatus':'source_map_reuse_not_established; OSM controls ODbL-1.0'},'geometry':mapping(geo)})
fc={'type':'FeatureCollection','name':'Eger 2016 regulatory planning units, original vector paths','features':features};out=root/'eger-planning-units.geojson';out.write_text(json.dumps(fc,ensure_ascii=False,separators=(',',':'))+'\n')
shutil.copyfile(sourcepdf,root/'eger-map-2016.pdf')
shutil.copyfile(tmp/'eger-vector-paths.json',root/'eger-pdf-vector-paths.json')
proof={'schemaVersion':1,'municipality':'Eger','sourceUrl':sourceurl,'sourceSha256':docsha,'sourcePdfPage':1,'sourceScale':'1:15000','outputFeatureCount':len(features),'boundaryKind':'planning_unit','originalVectorPathCount':33,'exportedNamedPathCount':32,'excludedPaths':[{'pdfDrawingIndex':165652,'reason':'Unlabelled TSZT road/area overlay; no defensible unique quarter or planning-unit label.'}],'affineToEov':j['affineToEov'],'boundaryMatchResidualMeters':j['boundaryMatchResidualMeters'],'calibrationTarget':{'osmRelationId':1418156,'epsg':23700,'source':'Actual municipal boundary from Hungary2026-11-12 PBF; not neighborhood proximity geometry'},'geometryProcessing':['Original colored PDF fill line segments extracted with PyMuPDF.','Line coordinate rounding at0.001PDFpoint removes only float serialization noise.','Polygonize source closed rings; do not generate point buffers or Voronoi polygons.','Subtract three separately filled nested plan areas from containing TSZT polygon.','Apply affine source-pixel→EOV fit; convert EPSG23700→EPSG4326 with pyproj.'],'checks':{'allPolygonsValid':True,'allOutputNamesManuallyVerifiedAgainstSource':True,'independentInteriorControlVerified':False,'usableForAddressAssignment':False,'rightsEstablished':False},'files':[]}
for f in [out,root/'eger-map-2016.pdf',root/'eger-pdf-vector-paths.json']:
 bb=f.read_bytes();proof['files'].append({'path':f.name,'bytes':len(bb),'sha256':hashlib.sha256(bb).hexdigest()})
(root/'eger-geometry-proof.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'features':len(features),'allValid':True,'sourceSha256':docsha,'output':str(out),'bytes':out.stat().st_size}))
